			$total_applicable = $iso_stats['total'] - $iso_stats['not_applicable'];

			if ( $total_applicable > 0 ) {
				return round( ( $iso_stats['implemented'] / $total_applicable ) * 100 );
			}

			return 0;
		}
	}
}
